/* total iterations the critical section is executed by each thread*/
unsigned long iters;  

/* amount of work performed in the critical section */
unsigned long grain = 1;

/* synchronization barrier */
pthread_barrier_t bar;

#ifdef REAL
struct timeval begin, end;
#endif 

double val = 0.0;
int total_threads = 0;

/* lock/mutex definition */
#if ( defined TAS_CAS || defined TTAS_CAS || defined TAS_TS || defined TTAS_TS ) 
spinlock_t lock;
#elif defined MUTEX
pthread_mutex_t mutex;
#endif

/* thread arguments data structure definition */
typedef struct {
    int my_id; //thread id
    int cpu_id; //logical cpu selected for this thread
} targs_t;

/* Function to be executed by each thread upon creation */
void* thread_fn(void *args)
{
    int i;
    targs_t *ta = (targs_t*)args;
    cpu_set_t mask;
    pthread_t me;
    int res;
    unsigned long it = 0;
    double in = 1.0, out;

    me = pthread_self();

    /* Each thread sets its own affinity. 
     * Specifically, thread i (i=0...nthreads-1), sets its 
     * affinity to cpu i. 
     */
    CPU_ZERO(&mask);
    CPU_SET(ta->cpu_id, &mask);
    res = pthread_setaffinity_np(me, sizeof(cpu_set_t), &mask);
    if (res) {
        fprintf(stderr, "Error in pthread_setaffinity_np.\n");
        exit(EXIT_FAILURE);
    }

#if DEBUG
    /* Make sure that affinity was set correctly */
    res = pthread_getaffinity_np(me, sizeof(cpu_set_t), &mask);
    if (res) {
        fprintf(stderr, "Error in pthread_getaffinity_np.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex);
    fprintf(stderr, "Thread %d started on cpus ", ta->my_id);
    for ( i = 0; i < CPU_SETSIZE; i++ )
        if (CPU_ISSET(i, &mask))
            fprintf(stderr, " %d", i);
    fprintf(stderr, "\n");
    pthread_mutex_unlock(&mutex);
#endif

    /* Begin of ROI: Thread "0" will start measurements at this point */
    pthread_barrier_wait(&bar);
    if (ta->my_id == 0)
#ifdef SNIPER
        SimRoiStart();
#elif defined REAL
        gettimeofday(&begin, NULL);
#endif
    pthread_barrier_wait(&bar);


    /* Execute critical section "iters" times */
    while (it++ < iters) {
        /* Critical section begin: acquire the lock */
#ifdef MUTEX
        pthread_mutex_lock(&mutex);
#elif defined TAS_CAS
        spin_lock_tas_cas(&lock);
#elif defined TTAS_CAS
        spin_lock_ttas_cas(&lock);
#elif defined TAS_TS
        spin_lock_tas_ts(&lock);
#elif defined TTAS_TS
        spin_lock_ttas_ts(&lock);
#endif

        /* do some dummy work just to spend time */
        out = dummy_work(in);
        val += out;

        /* Critical section end: release the lock */
#ifdef MUTEX
        pthread_mutex_unlock(&mutex);
#elif ( defined TAS_CAS || defined TTAS_CAS || defined TAS_TS || defined TTAS_TS ) 
        spin_unlock(&lock);
#endif
    }

    /* End of ROI: Thread "0" will stop measurements at this point */
    pthread_barrier_wait(&bar);
    if ( ta->my_id == 0 ) {
#ifdef SNIPER
        if (validate_counter(total_threads, iters) != EXIT_SUCCESS)
            exit(EXIT_FAILURE);
        SimRoiEnd();
#elif defined(REAL)
        gettimeofday(&end, NULL);
#endif
    }
    pthread_barrier_wait(&bar);


#if DEBUG
    pthread_mutex_lock(&mutex);
    fprintf(stderr, "Thread %d stopped with dummy result: %lf\n",ta->my_id, out);
    pthread_mutex_unlock(&mutex);
#endif

    pthread_exit(NULL);
} 

int main(int argc, char **argv)
{
    targs_t *targs;
    pthread_t *tids;
    int *cpu_ids;
    int i, res, nthreads;
    double elapsed;
    int exit_status = EXIT_SUCCESS;
    const char *cpu_list;

    if ( argc < 4 ) {
       printf("Usage: ./prog <nthreads> <iterations> <grain>\n");
       exit(EXIT_FAILURE);
    }

    nthreads = atoi(argv[1]);
    iters = atol(argv[2]);
    grain = atol(argv[3]);
    total_threads = nthreads;

    if (nthreads <= 0 || nthreads > CPU_SETSIZE || iters == 0 || grain == 0) {
        fprintf(stderr,
                "Invalid arguments: nthreads must be in [1, %d], "
                "iterations and grain must be positive.\n",
                CPU_SETSIZE);
        exit(EXIT_FAILURE);
    }

    /* allocate thread structures */
    tids = (pthread_t *)malloc_safe(nthreads * sizeof(pthread_t));
    targs = (targs_t *)malloc_safe(nthreads * sizeof(targs_t)); 
    cpu_ids = (int *)malloc_safe(nthreads * sizeof(int));

    cpu_list = getenv("LOCKS_CPU_LIST");
    if (cpu_list != NULL && cpu_list[0] != '\0') {
        if (parse_cpu_list(cpu_list, cpu_ids, nthreads) != nthreads) {
            fprintf(stderr,
                    "LOCKS_CPU_LIST must contain at least %d valid, unique "
                    "logical CPU IDs.\n",
                    nthreads);
            exit(EXIT_FAILURE);
        }
    } else {
        for (i = 0; i < nthreads; i++)
            cpu_ids[i] = i;
    }

    /* initialize barrier */
    pthread_barrier_init(&bar, NULL, nthreads);

    /* initialize lock or mutex */
#if ( defined TAS_CAS || defined TTAS_CAS || defined TAS_TS || defined TTAS_TS ) 
    spin_lock_init(&lock);
#elif defined MUTEX
    pthread_mutex_init(&mutex, NULL);
#endif

    /* create and spawn threads */
    for ( i = 0; i < nthreads; i++ ) {
        targs[i].my_id = i;
        targs[i].cpu_id = cpu_ids[i];
        res = pthread_create(&tids[i], NULL, thread_fn, (void*)&targs[i]);
        if ( res ) {
            fprintf(stderr, "Error in pthread_create.\n");
            exit(EXIT_FAILURE);
        }
    }

    /* join threads */
    for ( i = 0; i < nthreads; i++ ) {
        pthread_join(tids[i], NULL);
    }

#ifndef SNIPER
    exit_status = validate_counter(nthreads, iters);
#endif

#ifdef REAL
    elapsed = (end.tv_sec - begin.tv_sec) + (end.tv_usec - begin.tv_usec)/1000000.0; 
    fprintf(stdout, "Execution time:%lf seconds\n", elapsed);
#endif
#ifdef DEBUG
    fprintf(stdout, "Val:%lf\n", val);
#endif

    pthread_barrier_destroy(&bar);

    free(tids);
    free(targs);
    free(cpu_ids);

    return exit_status;
}


static int validate_counter(int nthreads, unsigned long iterations)
{
    double expected_val = (double)nthreads * (double)iterations;

    if (val != expected_val) {
        fprintf(stderr,
                "Validation failed: expected val %.0f, observed %.0f\n",
                expected_val, val);
        fflush(stderr);
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Validation: PASS (val=%.0f)\n", val);
    fflush(stdout);
    return EXIT_SUCCESS;
}


static int parse_cpu_list(const char *raw, int *cpu_ids, int required)
{
    char *copy, *token, *saveptr;
    int count = 0;

    copy = strdup(raw);
    if (copy == NULL)
        return -1;

    token = strtok_r(copy, ",", &saveptr);
    while (token != NULL && count < required) {
        char *end = NULL;
        long cpu = strtol(token, &end, 10);
        int i;

        while (end != NULL && *end == ' ')
            end++;

        if (token[0] == '\0' || end == token || (end != NULL && *end != '\0') ||
            cpu < 0 || cpu >= CPU_SETSIZE) {
            free(copy);
            return -1;
        }

        for (i = 0; i < count; i++) {
            if (cpu_ids[i] == cpu) {
                free(copy);
                return -1;
            }
        }

        cpu_ids[count++] = (int)cpu;
        token = strtok_r(NULL, ",", &saveptr);
    }

    free(copy);
    return count;
}


